const token = env.get("HOMELAB_REPORT_TOKEN");
const expectedJob = env.get("HOMELAB_REPORT_JOB_ID") || "c2c20bac-2f48-4605-b64a-5f7dfd40c743";
function reject(status, error) {
    msg.statusCode = status;
    msg.headers = {"Content-Type":"application/json","Cache-Control":"no-store"};
    msg.payload = {ok:false,error};
    return [null,msg];
}
if (!/^[a-f0-9]{64}$/i.test(token || "")) return reject(503,"Receiver not configured");
if (msg.req?.headers?.authorization !== "Bearer " + token) return reject(401,"Unauthorized");
const p = msg.payload;
if (!p || p.schema !== 1 || p.job_id !== expectedJob
    || typeof p.report_id !== "string" || !p.report_id || p.report_id.length > 200
    || typeof p.report !== "string" || !p.report.trim()
    || Buffer.byteLength(p.report,"utf8") > 32768
    || typeof p.generated_at !== "string" || !Number.isFinite(Date.parse(p.generated_at))
    || Date.parse(p.generated_at) > Date.now() + 300000
    || !["ok","error","skipped"].includes(p.last_run_status)) {
    return reject(400,"Invalid report");
}
msg.report = {
    generated_at:new Date(p.generated_at).toISOString(),
    report:p.report,
    report_id:p.report_id,
    job_id:p.job_id,
    last_run_status:p.last_run_status
};
delete msg.req.headers.authorization;
return [msg,null];

if (!msg.res || msg.res.headersSent) return null;
msg.statusCode = 503;
msg.headers = {"Content-Type":"application/json","Cache-Control":"no-store"};
msg.payload = {ok:false,error:"Home Assistant update failed"};
delete msg.error;
return msg;
